import os, json

EXCLUDE_DIRS = {
    'node_modules', 'node_modules-full', '.git', '.rork',
    '__pycache__', '.tmp-frames', '.tmp-ivx-frames',
    'dist', 'home', '.github'
}
EXCLUDE_PREFIXES = (
    'ivx_20step_', 'ivx_acceptance_test', 'phase1_test',
    'cert_test.py', 'web_qa_',
)
EXCLUDE_FILES = {
    '.env.example', '.gitignore', '.gitattributes', '.gitmodules',
    'bun.lock', 'GATE4_RORK_HISTORY_PURGE.md', 'PROJECT_SEPARATION.md',
    'IVX_CRITICAL_FILES_MANIFEST.json',
}

files = []
for root, dirs, fnames in os.walk('.'):
    dirs[:] = [d for d in dirs if d not in EXCLUDE_DIRS]
    for f in fnames:
        rel = os.path.join(root, f)[2:]
        if any(rel.startswith(p) for p in EXCLUDE_PREFIXES):
            continue
        if rel in EXCLUDE_FILES:
            continue
        if rel.endswith(('.png','.jpg','.jpeg','.gif','.webp','.ico')):
            continue
        files.append(rel)

files.sort()
json.dump(files, open('/tmp/local_files.json','w'))
print(f"LOCAL_COUNT={len(files)}")
PYEOF

